<div class="page-heading"><div><span class="eyebrow"><?= te('RECRUITMENT / DISTRIBUTION') ?></span><h1><?= te('One recruiting workspace.') ?></h1><p class="sub"><?= te('Manage candidates here. Configure external distribution only through verified provider integrations.') ?></p></div><a class="btn ghost" href="/requisitions"><?= te('Requisitions') ?></a></div>
<div class="grid g3"><?php foreach($catalog as $key=>$channel): ?><section class="card"><h2><?= e($channel[0]) ?></h2><span class="tag amber"><?= $key==='google_jobs'?'Structured data implemented':'Integration pending' ?></span><p class="muted"><?= e($channel[1]) ?></p><form method="post"><?= csrf_field() ?><input name="channel" type="hidden" value="<?= e($key) ?>"><label><?= te('Requisition') ?></label><select name="vacancy_id" required><?php foreach($vacancies as $vacancy): ?><option value="<?= (int)$vacancy['id'] ?>"><?= e($vacancy['title']) ?></option><?php endforeach; ?></select><button class="btn ghost"><?= te('Request channel setup') ?></button></form></section><?php endforeach; ?></div>
<div class="card"><h2><?= te('Connection requests') ?></h2><?php foreach($requests as $request): ?><p><?= e($request['title'].' · '.$catalog[$request['channel']][0].' · '.$request['status']) ?></p><?php endforeach; ?><p class="muted"><?= te('Requesting setup does not publish a job. The public job feed is at /job-feed; eligible application pages contain Google JobPosting data. Publication, inbound applications and messaging require separate provider acceptance and implementations.') ?></p></div>
